	switch len(options) {
	case 0:
		return ""
	case 1:
		return options[0]
	}

	instNums, _, instOK := parseVersion(installed)
	best, bestSameMajor := "", false
	for _, opt := range options {
		nums, _, ok := parseVersion(opt)
